class Solution {
    public int numIdenticalPairs(int[] nums){
        Map<Integer,Integer> count=new HashMap<>();
        int answer=0;
        for(int value:nums){
            answer+=count.getOrDefault(value,0);
            count.merge(value,1,Integer::sum);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun numIdenticalPairs(nums:IntArray):Int{
        val count=mutableMapOf<Int,Int>();
        var answer=0;
        for(value in nums){
            answer+=count[value]?:0;
            count[value]=(count[value]?:0)+1
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int numIdenticalPairs(vector<int>& nums){
        unordered_map<int,int> count;
        int answer=0;
        for(int value:nums){
            answer+=count[value];
            ++count[value];
        }
        return answer;
    }
};
